create table public.groups(id uuid primary key default gen_random_uuid(),school_id uuid not null,class_id uuid not null,teacher_id uuid not null,subject text not null,title text not null,archived boolean not null default false,unique(school_id,id),foreign key(school_id,class_id) references classes(school_id,id),foreign key(school_id,teacher_id) references memberships(school_id,id));
create table public.group_memberships(school_id uuid not null,group_id uuid not null,student_id uuid not null,state text not null check(state in ('pending','active','rejected','removed')),updated_at timestamptz not null default now(),primary key(group_id,student_id),foreign key(school_id,group_id) references groups(school_id,id),foreign key(school_id,student_id) references student_registry(school_id,student_id));
create table public.posts(id uuid primary key default gen_random_uuid(),school_id uuid not null,group_id uuid not null,author_id uuid not null,title text not null,body text not null,pinned boolean not null default false,revision int not null default 1,deleted boolean not null default false,created_at timestamptz not null default now(),unique(school_id,id),foreign key(school_id,group_id) references groups(school_id,id));
create table private.post_revisions(post_id uuid not null references posts(id),revision int not null,snapshot jsonb not null,editor_id uuid not null,created_at timestamptz not null default now(),primary key(post_id,revision));
create table public.post_reads(school_id uuid not null,post_id uuid not null,student_id uuid not null,read_at timestamptz not null default now(),primary key(post_id,student_id),foreign key(school_id,post_id) references posts(school_id,id));
create table public.query_policies(school_id uuid not null,teacher_id uuid not null,class_id uuid not null,subject text not null,hours int not null check(hours between 1 and 336),revision int not null default 1,primary key(teacher_id,class_id,subject),foreign key(school_id,teacher_id) references memberships(school_id,id),foreign key(school_id,class_id) references classes(school_id,id));
create table public.queries(id uuid primary key default gen_random_uuid(),school_id uuid not null,student_id uuid not null,teacher_id uuid not null,class_id uuid not null,subject text not null,topic text not null,state text not null default 'open' check(state in ('open','in_progress','answered','resolved','withdrawn')),cycle int not null default 1,created_at timestamptz not null default now(),unique(school_id,id),foreign key(school_id,student_id) references memberships(school_id,id),foreign key(school_id,teacher_id) references memberships(school_id,id),foreign key(school_id,class_id) references classes(school_id,id));
create table public.query_cycles(school_id uuid not null,query_id uuid not null,cycle int not null,teacher_id uuid not null,policy_hours int not null check(policy_hours between 1 and 336),policy_revision int not null,started_at timestamptz not null default now(),original_due_at timestamptz not null,due_at timestamptz not null,deadline_revision int not null default 1,first_response_at timestamptz,solution_delivered_at timestamptz,student_resolved_at timestamptz,primary key(query_id,cycle),foreign key(school_id,query_id) references queries(school_id,id));
create table public.query_messages(id uuid primary key default gen_random_uuid(),school_id uuid not null,query_id uuid not null,cycle int not null,author_id uuid not null,body text not null,kind text not null check(kind in ('question','clarification','reply','solution','information_request')),created_at timestamptz not null default now(),unique(school_id,id),foreign key(query_id,cycle) references query_cycles(query_id,cycle),foreign key(school_id,query_id) references queries(school_id,id));
create table public.deadline_revisions(id uuid primary key default gen_random_uuid(),school_id uuid not null,query_id uuid not null,cycle int not null,actor_id uuid not null,old_due_at timestamptz not null,new_due_at timestamptz not null,reason text not null,created_at timestamptz not null default now(),foreign key(query_id,cycle) references query_cycles(query_id,cycle));
create index query_due on query_cycles(due_at) where solution_delivered_at is null;
create table public.attachments(id uuid primary key default gen_random_uuid(),school_id uuid not null references schools(id),uploader_id uuid not null,post_id uuid,query_message_id uuid,object_key text not null unique,filename text not null,declared_type text not null,detected_type text,size bigint not null check(size between 1 and 10485760),checksum text not null,state text not null default 'quarantined' check(state in ('quarantined','scanning','clean','rejected','unavailable','deleted')),charged boolean not null default false,created_at timestamptz not null default now(),foreign key(school_id,post_id) references posts(school_id,id),foreign key(school_id,query_message_id) references query_messages(school_id,id),check(num_nonnulls(post_id,query_message_id)=1));
create function private.group_teacher(g uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.groups where id=g and school_id=private.school() and teacher_id=auth.uid() and not archived and private.role()='teacher' and private.assigned(class_id,subject))$$;
create function private.can_group(g uuid) returns boolean language sql stable security definer set search_path='' as $$select not private.active_attempt() and (private.group_teacher(g) or exists(select 1 from public.group_memberships gm join public.groups gr on gr.id=gm.group_id where gm.group_id=g and gm.student_id=auth.uid() and gm.state='active' and gm.school_id=private.school() and not gr.archived and private.role()='student'))$$;
create function private.can_query(q uuid) returns boolean language sql stable security definer set search_path='' as $$select not private.active_attempt() and exists(select 1 from public.queries where id=q and school_id=private.school() and ((student_id=auth.uid() and private.role()='student')or(teacher_id=auth.uid() and private.role()='teacher' and private.assigned(class_id,subject))))$$;
create function public.create_group(p jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();g uuid;begin perform private.require_access(s,true);if private.role()<>'teacher' or not private.assigned((p->>'classId')::uuid,p->>'subject') then raise exception 'FORBIDDEN' using errcode='42501';end if;insert into public.groups(school_id,class_id,teacher_id,subject,title)values(s,(p->>'classId')::uuid,auth.uid(),p->>'subject',p->>'title')returning id into g;perform private.audit(s,'group.created',g);return g;end$$;
create function public.set_group_member(p jsonb) returns void language plpgsql security definer set search_path='' as $$declare g public.groups;u uuid:=(p->>'studentId')::uuid;st text:=p->>'state';begin select * into g from public.groups where id=(p->>'groupId')::uuid;perform private.require_access(g.school_id,true);perform private.learning_access();if not private.group_teacher(g.id) then if private.role()<>'student' or u<>auth.uid() or st<>'pending' then raise exception 'FORBIDDEN' using errcode='42501';end if;end if;if not exists(select 1 from public.enrollments where class_id=g.class_id and student_id=u and active) then raise exception 'INVALID_MEMBER';end if;insert into public.group_memberships values(g.school_id,g.id,u,st,now())on conflict(group_id,student_id)do update set state=excluded.state,updated_at=now() where private.group_teacher(g.id) or group_memberships.state in ('rejected','removed');perform private.audit(g.school_id,'group.membership',u,null,jsonb_build_object('state',st));end$$;
create function public.write_post(p jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare g public.groups;po public.posts;begin select * into g from public.groups where id=(p->>'groupId')::uuid;perform private.require_access(g.school_id,true);if not private.group_teacher(g.id) then raise exception 'FORBIDDEN' using errcode='42501';end if;if p->>'postId' is null then insert into public.posts(school_id,group_id,author_id,title,body,pinned)values(g.school_id,g.id,auth.uid(),p->>'title',p->>'body',coalesce((p->>'pinned')::boolean,false))returning * into po;else update public.posts set title=p->>'title',body=p->>'body',pinned=coalesce((p->>'pinned')::boolean,false),deleted=coalesce((p->>'deleted')::boolean,false),revision=revision+1 where id=(p->>'postId')::uuid and group_id=g.id and revision=(p->>'revision')::int returning * into po;if not found then raise exception 'STALE_REVISION';end if;end if;insert into private.post_revisions values(po.id,po.revision,to_jsonb(po),auth.uid(),now());insert into public.notifications(school_id,recipient_id,event_key,type,resource_id)select g.school_id,student_id,'post:'||po.id||':'||po.revision,'group.post',po.id from public.group_memberships where group_id=g.id and state='active' on conflict do nothing;perform private.audit(g.school_id,'post.changed',po.id);return po.id;end$$;
create function public.set_query_policy(p jsonb) returns void language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();begin perform private.require_access(s,true);if private.role()<>'teacher' or not private.assigned((p->>'classId')::uuid,p->>'subject')then raise exception 'FORBIDDEN' using errcode='42501';end if;insert into public.query_policies values(s,auth.uid(),(p->>'classId')::uuid,p->>'subject',(p->>'hours')::int,1)on conflict(teacher_id,class_id,subject)do update set hours=excluded.hours,revision=query_policies.revision+1;perform private.audit(s,'query.policy',auth.uid());end$$;
create function public.create_query(p jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();pol public.query_policies;q uuid;begin perform private.require_access(s,true);perform private.learning_access();if private.role()<>'student' or not exists(select 1 from public.enrollments where student_id=auth.uid() and class_id=(p->>'classId')::uuid and active) or not exists(select 1 from public.teacher_assignments a join public.memberships m on m.id=a.teacher_id where a.class_id=(p->>'classId')::uuid and a.teacher_id=(p->>'teacherId')::uuid and a.subject=p->>'subject' and m.active)then raise exception 'FORBIDDEN' using errcode='42501';end if;select * into pol from public.query_policies where teacher_id=(p->>'teacherId')::uuid and class_id=(p->>'classId')::uuid and subject=p->>'subject';if not found then pol.school_id:=s;pol.teacher_id:=(p->>'teacherId')::uuid;pol.class_id:=(p->>'classId')::uuid;pol.subject:=p->>'subject';select hours,revision into pol.hours,pol.revision from public.teacher_query_defaults where teacher_id=pol.teacher_id;if not found then raise exception 'QUERY_POLICY_NOT_CONFIGURED';end if;end if;insert into public.queries(school_id,student_id,teacher_id,class_id,subject,topic)values(s,auth.uid(),pol.teacher_id,pol.class_id,pol.subject,p->>'topic')returning id into q;insert into public.query_cycles values(s,q,1,pol.teacher_id,pol.hours,pol.revision,now(),now()+make_interval(hours=>pol.hours),now()+make_interval(hours=>pol.hours),1,null,null,null);insert into public.query_messages(school_id,query_id,cycle,author_id,body,kind)values(s,q,1,auth.uid(),p->>'body','question');insert into public.notifications(school_id,recipient_id,event_key,type,resource_id)values(s,auth.uid(),'query:'||q,'query.created',q),(s,pol.teacher_id,'query:'||q,'query.created',q);perform private.audit(s,'query.created',q);return q;end$$;
create function public.reply_query(p jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare q public.queries;cy public.query_cycles;pol public.query_policies;mid uuid;k text:=p->>'kind';begin select * into q from public.queries where id=(p->>'queryId')::uuid for update;if not private.can_query(q.id) or q.state='withdrawn' then raise exception 'FORBIDDEN' using errcode='42501';end if;select * into cy from public.query_cycles where query_id=q.id and cycle=q.cycle;if q.student_id=auth.uid() then if k<>'clarification' then raise exception 'FORBIDDEN' using errcode='42501';end if;if q.state in ('answered','resolved') then select * into pol from public.query_policies where teacher_id=q.teacher_id and class_id=q.class_id and subject=q.subject;if not found then pol.teacher_id:=q.teacher_id;select hours,revision into pol.hours,pol.revision from public.teacher_query_defaults where teacher_id=q.teacher_id;if not found then raise exception 'QUERY_POLICY_NOT_CONFIGURED';end if;end if;q.cycle:=q.cycle+1;insert into public.query_cycles values(q.school_id,q.id,q.cycle,q.teacher_id,pol.hours,pol.revision,now(),now()+make_interval(hours=>pol.hours),now()+make_interval(hours=>pol.hours),1,null,null,null);update public.queries set cycle=q.cycle,state='open' where id=q.id;end if;else if k not in ('reply','solution','information_request')then raise exception 'INVALID_REPLY';end if;update public.query_cycles set first_response_at=coalesce(first_response_at,now()),solution_delivered_at=case when k='solution' then coalesce(solution_delivered_at,now())else solution_delivered_at end where query_id=q.id and cycle=q.cycle;update public.queries set state=case when k='solution' then 'answered' else 'in_progress' end where id=q.id;end if;insert into public.query_messages(school_id,query_id,cycle,author_id,body,kind)values(q.school_id,q.id,q.cycle,auth.uid(),p->>'body',k)returning id into mid;insert into public.notifications(school_id,recipient_id,event_key,type,resource_id)values(q.school_id,case when auth.uid()=q.student_id then q.teacher_id else q.student_id end,'reply:'||mid,'query.reply',q.id);perform private.audit(q.school_id,'query.replied',q.id);return mid;end$$;
create function public.transition_query(p jsonb) returns void language plpgsql security definer set search_path='' as $$declare q public.queries;begin select * into q from public.queries where id=(p->>'queryId')::uuid for update;if not private.can_query(q.id) or q.student_id<>auth.uid()then raise exception 'FORBIDDEN' using errcode='42501';end if;if p->>'state'='resolved' and q.state='answered' then update public.query_cycles set student_resolved_at=now()where query_id=q.id and cycle=q.cycle;elsif p->>'state'='withdrawn' and length(p->>'reason')>0 then null;else raise exception 'INVALID_TRANSITION';end if;update public.queries set state=p->>'state' where id=q.id;perform private.audit(q.school_id,'query.'||(p->>'state'),q.id,p->>'reason');end$$;
create function public.revise_deadline(p jsonb) returns void language plpgsql security definer set search_path='' as $$declare q public.queries;cy public.query_cycles;nd timestamptz:=(p->>'dueAt')::timestamptz;begin select * into q from public.queries where id=(p->>'queryId')::uuid for update;if not private.can_query(q.id) or auth.uid()<>q.teacher_id or length(coalesce(p->>'reason',''))<1 then raise exception 'FORBIDDEN' using errcode='42501';end if;select * into cy from public.query_cycles where query_id=q.id and cycle=q.cycle;if cy.deadline_revision<>(p->>'revision')::int then raise exception 'STALE_REVISION';end if;insert into public.deadline_revisions(school_id,query_id,cycle,actor_id,old_due_at,new_due_at,reason)values(q.school_id,q.id,q.cycle,auth.uid(),cy.due_at,nd,p->>'reason');update public.query_cycles set due_at=nd,deadline_revision=deadline_revision+1 where query_id=q.id and cycle=q.cycle;insert into public.notifications(school_id,recipient_id,event_key,type,resource_id,metadata)values(q.school_id,q.student_id,'deadline:'||q.id||':'||q.cycle||':'||(cy.deadline_revision+1),'query.deadline',q.id,jsonb_build_object('oldDueAt',cy.due_at,'newDueAt',nd,'reason',p->>'reason'));perform private.audit(q.school_id,'query.deadline',q.id,p->>'reason');end$$;
